mapper.select:
SELECT s.file_path AS filePath, s.title AS TITLE, s.duration AS DURATION, GROUP_CONCAT(DISTINCT a.artist_name ORDER BY sa.sort_order SEPARATOR ',') AS ARTISTNAMES, al.album_name AS ALBUMNAME FROM song s LEFT JOIN song_artist sa ON s.id = sa.song_id LEFT JOIN artist a ON sa.artist_id = a.id LEFT JOIN album al ON s.album_id = al.id WHERE s.file_path IN
#{p}
GROUP BY s.id

SELECT s.file_path AS FILEPATH, s.title AS TITLE, s.file_name AS FILE_NAME, s.file_format AS FILE_FORMAT, s.file_size AS FILE_SIZE, s.file_hash AS FILE_HASH, s.fingerprint AS FINGERPRINT, s.duration AS DURATION, s.cover_path AS COVER_PATH, s."year" AS "YEAR", s.bitrate AS BITRATE, s.sample_rate AS SAMPLE_RATE, s.channels AS CHANNELS, s.bits_per_sample AS BITS_PER_SAMPLE, s.language AS LANGUAGE, s.album_id AS ALBUM_ID, s.track_number AS TRACK_NUMBER, s.disc_number AS DISC_NUMBER, s.track_gain AS TRACK_GAIN, s.track_peak AS TRACK_PEAK, s.composer AS COMPOSER, s.lyricist AS LYRICIST, s.arranger AS ARRANGER, s.producer AS PRODUCER, s.file_mtime AS FILE_MTIME, al.album_name AS ALBUM_NAME, al.album_year AS ALBUM_YEAR, al.introduction AS ALBUM_INTRODUCTION, al.company AS ALBUM_COMPANY, al.language AS ALBUM_LANGUAGE, GROUP_CONCAT(DISTINCT CONCAT(a.artist_name, '::', COALESCE(a.country, '')) ORDER BY sa.sort_order, a.id SEPARATOR '||') AS ARTIST_DATA, GROUP_CONCAT(DISTINCT st.style_name SEPARATOR '||') AS STYLE_NAMES, GROUP_CONCAT(DISTINCT l.content SEPARATOR '|||') AS LYRIC_CONTENTS FROM song s LEFT JOIN album al ON s.album_id = al.id LEFT JOIN song_artist sa ON s.id = sa.song_id LEFT JOIN artist a ON sa.artist_id = a.id LEFT JOIN song_style ss ON s.id = ss.song_id LEFT JOIN style st ON ss.style_id = st.id LEFT JOIN lyric l ON s.id = l.song_id WHERE s.file_path IN
#{p}
GROUP BY s.id, al.id
